UPDATE "Club" SET "status" = 'ACTIVE', "lastVerifiedAt" = '2026-11-08', "description" = 'Mahj Mixers'' own site says: "Whether you''re brand new to American Mahjong, building your confidence, or ready to sharpen your skills, Mahj Mixers has an option for you." Guided open play (not a lesson; some experience needed) at Ryleigh''s Oyster in Lutherville-Timonium. Dates are on the group''s booking page.', "website" = 'https://www.mahjmixers.com/', "sourceUrl" = 'https://www.mahjmixers.com/' WHERE "slug" = 'baltimore-mahj-mixers-guided-open-play-at-ryleigh-s-oyster' AND "status" = 'NEEDS_REVIEW';
UPDATE "Club" SET "status" = 'ACTIVE', "lastVerifiedAt" = '2026-11-08', "description" = 'The City of San Diego''s Allied Gardens Recreation Center page lists "Open Play American Mahjong", Mondays 1 to 4 p.m. in the Gardens Room, free.', "website" = 'https://www.sandiego.gov/park-and-recreation/centers/recctr/allied', "sourceUrl" = 'https://www.sandiego.gov/park-and-recreation/centers/recctr/allied' WHERE "slug" = 'san-diego-san-diego-american-mah-jongg-meetup-allied-gardens-rec-center' AND "status" = 'NEEDS_REVIEW';
UPDATE "Club" SET "status" = 'ACTIVE', "lastVerifiedAt" = '2026-11-08', "description" = 'City of San Diego Parks & Recreation listing for the Nobel Recreation Center (Nobel Meeting Room 2): "American Mahjongg is played with four players using tiles stamped with Chinese symbols." Experienced players welcome; bring your own set. Thursdays Sep 3 - Nov 19 2026 and Saturdays Sep 5 - Nov 7 2026; the fee is shown at registration.', "website" = 'https://www.active.com/san-diego-ca/mah-jong/classes/american-mahjongg-2026-110529479', "sourceUrl" = 'https://www.active.com/san-diego-ca/mah-jong/classes/american-mahjongg-2026-110529479' WHERE "slug" = 'san-diego-san-diego-american-mah-jongg-meetup-nobel-rec-center' AND "status" = 'NEEDS_REVIEW';
UPDATE "Club" SET "status" = 'ACTIVE', "lastVerifiedAt" = '2026-11-08', "description" = 'Its own site says: "The National Mah Jongg League (NMLJ) formed in 1937 to standardize the rules for American mahjongg." and "I learned American mahjongg with a group of friends when my kids were in preschool". Classes and social leagues in Marin County.', "website" = 'https://mahjonmymind.com/', "sourceUrl" = 'https://mahjonmymind.com/' WHERE "slug" = 'marin-mahj-on-my-mind-marin-sf-bay-area' AND "status" = 'NEEDS_REVIEW';
UPDATE "Club" SET "status" = 'ACTIVE', "lastVerifiedAt" = '2026-11-08', "description" = 'MS Mahj (Linda McKnight) teaches American Mah Jongg in the Memphis area; its own event page says the beginner lessons cost "$75 and includes the National Mah Jongg League official playing card". Lessons at the Memphis Chess Club; its other sessions are listed under Olive Branch.', "website" = 'https://msmahj.com', "sourceUrl" = 'https://msmahj.com' WHERE "slug" = 'memphis-mah-jongg-lessons-at-memphis-chess-club-ms-mahj-linda-mcknight' AND "status" = 'NEEDS_REVIEW';
UPDATE "Instructor" SET "status" = 'ACTIVE', "lastVerifiedAt" = '2026-11-08', "notes" = 'Missy''s own site says she "started teaching American mahjong in Nashville, Chicago and Lake Geneva in 2024"; her lessons page offers free online tutorials. In-person formats, prices and dated sessions are not listed.', "website" = 'https://www.missymahjong.com', "sourceUrl" = 'https://www.missymahjong.com' WHERE "slug" = 'nashville-missy-mahjong-llc' AND "status" = 'NEEDS_REVIEW';
UPDATE "Instructor" SET "status" = 'ACTIVE', "lastVerifiedAt" = '2026-11-08', "notes" = 'Its own classes page says: "Learning the National Mah Jongg League rules of play" (beginner curriculum). Private lessons, group series of 4-5 lessons and supervised play; schedule by contacting the instructor. The same instructor is listed under Phoenix.', "website" = 'https://majbydaron.com', "sourceUrl" = 'https://majbydaron.com' WHERE "slug" = 'scottsdale-maj-by-daron-daron-barness' AND "status" = 'NEEDS_REVIEW';
UPDATE "Club" SET "status" = 'INACTIVE', "updatedAt" = CURRENT_TIMESTAMP WHERE "slug" IN ('batavia-lisa-blue-tiger-mahj-club', 'seattle-american-mahjong-at-the-j-stroum-jewish-community-center') AND "status" = 'NEEDS_REVIEW';
