VALUES ('club_scarsdale-scarsdale-public-library-mah-jongg-open-play', 'Scarsdale Public Library - Mah Jongg Open Play', 'scarsdale-scarsdale-public-library-mah-jongg-open-play', 'Library open play: "the National Mah Jongg League (NMJL) 2026 card and rules"; 3- or 4-hand games and Siamese variants. Some tables accommodate beginners but no formal instruction is provided. The library supplies a limited number of sets; registration may be required and sessions can fill.', (SELECT id FROM City WHERE name = 'Scarsdale' AND state = 'NY'), '54 Olmsted Road, Scarsdale, NY 10583', 'https://www.scarsdalelibrary.org', '914-722-1300', NULL, NULL, NULL, 1, 0, 1, 1, 0, 1, NULL, 'Periodic sessions in Meeting Room North South; see library calendar for dates.', 'https://www.scarsdalelibrary.org/node/150254/export.ics', '2026-11-06', 'ACTIVE')
