-- The "Marin, Local for Holidays" session looks like a holiday market, not a mahjong session: held for review.
UPDATE "Event" SET "status" = 'NEEDS_REVIEW' WHERE "name" LIKE 'Marin, Local for Holidays%' AND "status" = 'ACTIVE';
-- Indianapolis (3 owners + 5 Zionsville lessons) and Marin (2 clubs, 1 teacher, 5 sessions) now have five or more active rows: published with intros.
UPDATE "City" SET "published" = 1, "intro" = 'Indianapolis-area American mahjong is spread across the northern suburbs. Fishers Mah Jongg Center is a dedicated centre that follows National Mah Jongg League rules and welcomes members and non-members, 317 Mahj Collective hosts lessons, community events and Mahjong Mondays, and Meet at Mahj teaches 101 and 103 sessions at its studio in Zionsville. Check each group''s page for dates and booking. If you are new, start with a Mahjong 101 lesson at the Zionsville studio before joining open play.' WHERE "slug" = 'indianapolis';
UPDATE "City" SET "published" = 1, "intro" = 'Marin County''s American mahjong runs through a community centre and a local organiser. Marinwood Community Center in San Rafael offers a beginner American Mah Jongg course that teaches players to read the National Mah Jongg League card, plus a drop-in open play on Wednesday afternoons, and Mahj On My Mind runs classes and winter social leagues. Check dates before you go. If you are new, the Marinwood beginner course is the best way in before you join the open play or a social league.' WHERE "slug" = 'marin';
